function selectNvPoint(i){if(!nvSession||nvCapturing||i<0||i>=nvSession.plan.length)return;nvIndex=i;$('nvRef').value=nativeChecks.find(r=>r.index===i)?.reference??nvSession.plan[i].ref??'';$('nvTempRef').value=nativeChecks.find(r=>r.index===i)?.tempReference??nvSession.plan[i].temperature??'';refreshVerification()}
