on('nvCapture',async()=>{if(!nvSession||nvDone||nvCapturing||navigating)return;const session=nvSession,i=nvIndex,pressure=session.mode!=='temperature',thermal=session.mode!=='pressure',ref=pressure?n('nvRef'):null,tempRef=thermal?n('nvTempRef'):null;nvCapturing=true;refreshVerification();try{if(pressure&&(!Number.isFinite(ref)||ref<0||ref>100))throw Error('Referenzdruck 0–100 % FS eingeben.');if(thermal&&(!Number.isFinite(tempRef)||tempRef< -50||tempRef>150))throw Error('Referenztemperatur -50 bis 150 °C eingeben.');const r=await hardware.outputCapture();if(nvSession!==session)return;if(thermal&&!r.temperatureCalibrated)throw Error('Kein bestätigter kalibrierter Temperaturausgang. Druckprüfung ohne Temperatur wählen oder Temperaturkonfiguration prüfen.');const {lo,hi,tol,tempTol}=session,measured=pressure?(r.raw*100/16384-lo)*100/(hi-lo):null,error=pressure?measured-ref:null,tempEstimate=thermal?r.tempCode*200/2048-50:null,tempError=thermal?tempEstimate-tempRef:null,record={...session.plan[i],index:i,time:new Date().toISOString(),reference:ref,estimate:measured,error,tolerance:pressure?tol:null,tempReference:tempRef,tempEstimate,tempError,tempTolerance:thermal?tempTol:null,pass:(!pressure||Math.abs(error)<=tol)&&(!thermal||Math.abs(tempError)<=tempTol),raw:r.raw,tempCode:r.tempCode,targetLow:lo,targetHigh:hi};const old=nativeChecks.findIndex(v=>v.index===i);if(old>=0)nativeChecks.splice(old,1,record);else nativeChecks.push(record);$('nvStatus').textContent='Prüfpunkt '+(i+1)+' aufgenommen.'}catch(e){$('nvStatus').textContent=e.message}finally{nvCapturing=false;refreshVerification()}});
