function requestNavigation(target){if(navigating)return;homeTarget=target;const hw=hardware?.navigationState?.()||{},critical=hw.critical&&!nvCapturing&&!hardwareLogActive,unfinished=!!activeTask||!!(nvSession&&!nvDone)||hardwareLogActive||!!timer||hw.recording||nvCapturing;if(!critical&&!unfinished){finishHome();return}const dialog=$('guidedHomeConfirm');$('guidedHomeConfirmTitle').textContent=target==='guided'?'Zur Aufgabenauswahl?':'Ansicht wechseln?';$('guidedHomeAbort').textContent=target==='guided'?'Vorgang abbrechen & zur Aufgabenauswahl':'Vorgang abbrechen & Ansicht wechseln';$('guidedHomeConfirmMessage').textContent=critical?'Ein Sensor- oder Schreibvorgang läuft. Bitte diesen zuerst fertig machen.':'Aktive Aufgabe: '+(activeTask==='verification'?'Nachmessung':activeTask==='calibration'?'Kalibrierung':hardwareLogActive||hw.recording?'Testaufzeichnung':'Vorgang')+'. Möchtest du abbrechen? Aufgenommene Messwerte werden lokal archiviert. Bereits geänderte Sensoreinstellungen bleiben unverändert. Der USB-Adapter bleibt verbunden.'+(hw.recovery31015?' Achtung: ZSC31015 befindet sich möglicherweise in der temporären Unity-Konfiguration. Original-EEPROM zuerst wiederherstellen.':'');$('guidedHomeAbort').hidden=!!critical;$('guidedHomeConfirmStatus').hidden=true;if(!dialog.open)dialog.showModal()}
