on('guidedHomeAbort',async()=>{if(navigating)return;const hw=hardware?.navigationState?.()||{};if(hw.critical&&!nvCapturing&&!hardwareLogActive){requestHome();return}navigating=true;$('guidedHomeAbort').disabled=true;$('guidedHomeStay').disabled=true;$('guidedHomeConfirmStatus').hidden=false;$('guidedHomeConfirmStatus').textContent='Vorgang wird beendet und archiviert …';try{const wasLog=hardwareLogActive||!!timer||hw.recording;stopLog();hardware?.stopNativeRecording?.();for(let i=0;i<300&&(nvCapturing||hardware?.navigationState?.().critical||hardware?.navigationState?.().recording);i++)await new Promise(r=>setTimeout(r,100));if(nvCapturing||hardware?.navigationState?.().critical||hardware?.navigationState?.().recording)throw Error('Laufende Messung noch nicht beendet.');if(nvSession&&!nvDone)saveVerification('aborted');if(activeTask==='calibration'&&!archiveCalibrationDraft('aborted')&&fit){const records=safeGet('renesas-archive',[]);records.unshift({...report(),type:'calibration',status:'aborted'});safeSet('renesas-archive',records.slice(0,100))}if(wasLog){const nativeLog=hardware?.recordingDraft?.();const records=safeGet('renesas-archive',[]);if(logs.length)records.unshift({...logRecord(),status:'aborted'});if(nativeLog?.length)records.unshift({schema:1,type:'testlog',status:'aborted',model:model.id,created:new Date().toISOString(),logs:nativeLog});safeSet('renesas-archive',records.slice(0,100))}finishHome()}catch(e){$('guidedHomeConfirmStatus').textContent=e.message}finally{navigating=false;$('guidedHomeAbort').disabled=false;$('guidedHomeStay').disabled=false}});

on('save',()=>act(()=>{const list=safeGet('renesas-archive',[]);list.unshift(report());safeSet('renesas-archive',list.slice(0,100));$('saveMsg').textContent='Offline-Bericht lokal gespeichert.'}));
function archive(){const list=safeGet('renesas-archive',[]),root=$('archiveList');root.replaceChildren();if(!list.length){root.textContent='Keine gespeicherten Berichte.';return}list.forEach(r=>{const card=document.createElement('div');card.className='callout';const title=document.createElement('strong');title.textContent=r.model.toUpperCase()+' · '+r.created+' · '+(r.type==='testlog'?'Test / Logging':r.type==='verification'?'Nachmessung':r.synthetic?'Demo':'Offline');card.append(title,document.createTextNode(' '));const b=document.createElement('button');b.textContent='JSON herunterladen';b.onclick=()=>download(r.model+'-offline.json',JSON.stringify(r,null,2),'application/json');card.append(b);root.append(card)})}
on('refreshArchive',archive);on('print',()=>act(()=>{const r=report(),w=window.open('','_blank');if(!w)throw Error('Popup-Freigabe erforderlich.');w.opener=null;const doc=w.document;doc.title='Kalibrierbericht · '+r.model;const style=doc.createElement('style');style.textContent='body{font:13px system-ui;color:#25354a;margin:32px}h1{font-size:24px}h2{font-size:17px;margin-top:25px}table{border-collapse:collapse;width:100%}th,td{padding:7px;border-bottom:1px solid #dce4ed;text-align:left}p{line-height:1.5}svg{width:100%;height:180px}';doc.head.append(style);const add=(tag,str)=>{const e=doc.createElement(tag);e.textContent=str;doc.body.append(e);return e};const table=(headers,rows)=>{const t=doc.createElement('table');for(const [i,vals] of [headers,...rows].entries()){const tr=t.insertRow();for(const v of vals){const c=doc.createElement(i?'td':'th');c.textContent=typeof v==='number'?fmt(v):String(v);tr.append(c)}}doc.body.append(t)};add('h1','Kalibrierbericht · '+r.model.toUpperCase());add('p',r.created+' · '+(r.synthetic?'Demo / synthetische Daten':'Manuelle Offline-Messpunkte')+' · Keine Hardwareprogrammierung');add('h2','Messbereich und Modell');add('p',r.range.join(' … ')+' '+r.unit+' · '+r.fit.kind+' · Max. Residuum '+fmt(r.fit.maxError));add('h2','Kalibrierpunkte');table(['ADC_S','Referenz','Temperatur °C','Residuum'],r.points.map((p,i)=>[p.raw,p.reference,p.temp,r.fit.residuals[i]]));add('h2','Unabhängige Nachmessung');table(['ADC_S','Referenz','Berechnet','Fehler % FS','Toleranz','Status'],r.checks.map(c=>[c.raw,c.reference,c.estimate,c.percent,c.tolerance,c.pass?'OK':'Ausserhalb']));if(!r.checks.length)add('p','Keine unabhängigen Prüfpunkte.');add('h2','Modellparameter');add('p','x = (ADC_S − '+fmt(r.fit.center)+') / '+fmt(r.fit.scale)+'; Koeffizienten: '+r.fit.coefficients.map(fmt).join(' / '));add('p','Die Parameter sind keine Renesas-Registerwerte.');w.print()}));
