hardware=installHardware({calibration:nativeSnapshot,calibrationStatus:nativeStatus,calibrationAlert:nativeAlert,connectionLost:()=>{nativeReset();clearViewer();clearBridge()},live:displayLive,model:()=>model.id,mode:s=>{hardwareState=s;port=s.port?true:undefined;if(s.port){demo=false;if(timer){clearInterval(timer);timer=undefined}}else if(hardwareLogActive){stopLog()}updateMode()},log:t=>{$('serialLog').textContent=($('serialLog').textContent+'\n'+t).slice(-20000)},read:r=>{setBridgeBackup(r);if(r.fields.words)showViewer(r.model,r.fields.words,{source:'Hardware · EEPROM doppelt gelesen',backup:r});else showViewer(r.model,r.bytes.map((b,i)=>({address:i.toString(16).padStart(2,'0').toUpperCase(),name:'Byte '+i,value:b.toString(16).padStart(2,'0').toUpperCase()})),{source:'Hardware · EEPROM-Bytefolge doppelt gelesen',backup:r});if(r.model==='zsc31010'){$('hex').value=r.bytes.map(b=>b.toString(16).padStart(2,'0')).join(' ');$('hexView').click()}else if(r.fields.words){$('hex').value=r.fields.words.map(w=>w.value).join(' ');$('hexResult').textContent=JSON.stringify(r.fields.words,null,2)}else{$('hexResult').textContent=JSON.stringify(r,null,2)}},connectStatus:t=>{$('conn').textContent=t}});
